INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷258", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。疑似转录讹字保留并单独注明。", "url": "https://github.com/greed-216/histree/blob/4d35696319726b523bd624f2370cb2cf7faa6b43/resources/derived/tongjian/258.txt", "note": "卷258大顺二年条；书、卷、年、段落及行号见批次账本。", "id": "d3357220-e689-5ebf-b1a9-6ec7b921c7de"}, {"title": "新五代史·卷68·闽世家·陈岩范晖段", "source_type": "primary", "author": "欧阳修", "edition": "仓库PDF逐页电子提取文本；摘取PDF第1476页原text，不改字，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/19%E6%96%B0%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L1476", "note": "原PDF页1476，对应卷68闽世家；仅补当前主段的身份与纪年异说。", "id": "85c15395-be00-5841-9e73-4a1e98e00e95"}, {"title": "十国春秋·卷39·王宗涤姓名摘录", "source_type": "primary", "author": "吴任臣", "edition": "维基文库电子文本逐字摘录，未核纸本，不是整卷快照。", "url": "https://github.com/greed-216/histree/blob/32fe43f3d1dfa38344bf53b23870638f899f3e99/resources/derived/shiguochunqiu/039-hua-hong-excerpt.txt", "note": "只补对应华洪身份，不提前录其后来事迹。", "id": "dbf18a71-4850-58e5-94e5-c0cd79f63e68"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "丁会", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：丁会。", "biography": null, "status": "draft", "id": "1e293174-0688-58bb-b1bb-453af473382e"}, {"name": "张归霸", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的张归霸，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "1a80805c-f540-5c03-9a56-44ea619f4f14"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "杨守立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨守立。", "biography": null, "status": "draft", "id": "49818612-f0b9-5431-b7c7-5b767839fb45"}, {"name": "刘景宣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：刘景宣。", "biography": null, "status": "draft", "id": "4588bc93-43ed-56e6-83f4-dd2d74462ad9"}, {"name": "西门君遂", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：西门君遂。", "biography": null, "status": "draft", "id": "ee5a7388-72a2-5742-ad8e-a61393243757"}, {"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "似先知", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：似先知。", "biography": null, "status": "draft", "id": "98f7f0ab-0f8c-5130-bb6e-48a54fdd45b0"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "stat