INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "丁会张归霸金乡大破朱瑾", "start_year": 891, "end_year": 891, "time_original": "891年十二月乙酉", "dynasty": "唐", "description": "汴将丁会、张归霸与朱瑾在金乡交战，大败朱瑾，书载杀获殆尽，朱瑾单骑逃脱。", "phases": [], "location_name": "金乡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "80f33e98-013a-5e92-9fb3-255a6dd390ae"}, {"title": "李顺节带兵出入，刘景宣西门君遂奏疑", "start_year": null, "end_year": null, "time_original": "十二月戊子被杀前；确年日未载", "dynasty": "唐", "description": "《通鉴》述天威都将李顺节恃宠骄横、出入带兵。两军中尉刘景宣、西门君遂厌恶，上报皇帝担心其作乱。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6ba5bc66-e989-55ab-a771-d7fa5dfb1cdf"}, {"title": "李顺节银台门被召，似先知斩首", "start_year": 891, "end_year": 891, "time_original": "891年十二月戊子", "dynasty": "唐", "description": "刘景宣、西门君遂以诏召李顺节。李顺节入银台门后被邀至仗舍坐谈，供奉官似先知从后斩首，其随从喧噪而出。", "phases": [], "location_name": "银台门、仗舍", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "393c8e5f-71f3-5861-b38b-5e98f83bd69b"}, {"title": "三都军士劫掠永宁坊至暮才定", "start_year": 891, "end_year": 891, "time_original": "891年十二月戊子；李顺节被杀后", "dynasty": "唐", "description": "李顺节被杀后，天威、捧日、登封三都大掠永宁坊，直到傍晚才平定，百官上表称贺。", "phases": [], "location_name": "永宁坊", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4e649f09-8ef4-5ae6-a434-b69a4b870b2e"}, {"title": "孙儒焚苏常逼宣，钱镠复据苏州", "start_year": 891, "end_year": 891, "time_original": "891年十二月条；具体日未载", "dynasty": "唐", "description": "孙儒焚掠苏州常州，率军逼宣州；钱镠再次遣兵占据苏州。", "phases": [], "location_name": "苏州、常州、宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e3659740-cd47-5760-a479-6436621c8e1a"}, {"title": "杨行密受孙儒屡破，钱镠以兵食援助", "start_year": 891, "end_year": 891, "time_original": "891年十二月条；具体日未载", "dynasty": "唐", "description": "孙儒屡败杨行密军，书载旌旗辎重绵延百余里。杨行密向钱镠求救，钱镠以兵与粮食援助。", "phases": [], "location_name": "宣州、两浙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "04ef78b2-ba05-5484-844a-25fae8977983"}, {"title": "顾彦晖获东川节度使，宋道弼奉节", "start_year": 891, "end_year": 891, "time_original": "891年十二月条；具体日未载", "dynasty": "唐", "description": "朝廷任顾彦晖为东川节度使，遣中使宋道弼赐旌节。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "506cd2fd-a7e6-5a0a-b918-13e865bf5ac6"}, {"title": "杨守厚囚宋道弼夺节攻梓州", "start_year": 891, "end_year": 891, "time_original": "891年十二月条；赐节途中", "dynasty": "唐", "description": "杨守亮令杨守厚囚宋道弼、夺其旌节，并发兵攻梓州。", "phases": [], "location_name": "梓州、绵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "380ec799-1712-5c04-90e1-0405aeca01d6"}, {"title": "顾彦晖求援，王建遣四将并密谋擒顾", "start_year": 891, "end_year": 891, "time_original": "891年十二月癸卯、甲辰", "dynasty": "唐", "description": "癸卯顾彦晖向王建求救，甲辰王建遣华洪、李简、王宗侃、王宗弼救东川；王建密令破敌后趁顾彦晖报宴将其拘执。", "phases": [], "location_name": "东川、梓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "df7918f0-ba60-5d7a-a15f-9869baf20087"}, {"title": "王宗侃破七砦，杨守厚退绵州", "start_year": 891, "end_year": 891, "time_original": "891年十二月甲辰后", "dynasty": "唐", "description": "王宗侃攻破杨守厚七砦，杨守厚逃归绵州。", "phases": [], "location_name": "东川七砦、绵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6b451ca2-b945-5407-8fe9-9ed878873943"}, {"title": "王宗弼泄露王建谋，顾彦晖辞宴", "start_year": 891, "end_year": 891, "time_original": "891年十二月条；破七砦后", "dynasty": "唐", "description": "顾彦晖备犒礼，诸将回请宴饮；王宗弼告知王建密谋，顾彦晖以病推辞。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "608792b5-bb1b-5cd3-a0da-cf1170b3a5c1"}, {"title": "冯行袭取李继臻所据金州", "start_year": null, "end_year": null, "time_original": "初；确年日未载", "dynasty": "唐", "description": "《通鉴》追述李茂贞养子继臻据金州，均州刺史冯行袭攻取，朝廷任冯为昭信防御使，治金州。", "phases": [], "location_name": "金州、均州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "88073546-dcd1-5196-9dca-fd264a7da162"}, {"title": "冯行袭阻击杨守亮由金商袭京之谋", "start_year": null, "end_year": null, "time_original": "段内初后的记事；确年日未定", "dynasty": "唐", "description": "杨守亮计划自金州、商州袭京师，冯行袭迎击，大败其军。", "phases": [], "location_name": "金州、商州、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "06bf141e-ae72-5858-8d17-ba9499956fc0"}, {"title": "泾原获彰义军号增领渭武", "start_year": 891, "end_year": 891, "time_original": "891年；具体月日未载", "dynasty": "唐", "description": "朝廷赐泾原军号彰义，增加所领渭州、武州。", "phases": [], "location_name": "泾原、渭州、武州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "755c551c-ece5-53bd-870f-b03050deb1ac"}, {"title": "陈岩病召王潮未至而去世", "start_year": 891, "end_year": 891, "time_original": "891年；具体月日未载", "dynasty": "唐", "description": "福建观察使陈岩患病，遣使以书召泉州刺史王潮，想授军政，王潮尚未到而陈岩去世。", "phases": [], "location_name": "福建、泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7aca12dd-27f6-5a02-868c-cc2f278b8422"}, {"title": "范晖促军推留后并发兵拒王潮", "start_year": 891, "end_year": 891, "time_original": "891年；陈岩去世后", "dynasty": "唐", "description": "《通鉴》称陈岩妻弟、都将范晖劝将士推己为留后，发兵抵抗王潮。《新五代史》称范晖为陈岩之婿，亲属记载不同。", "phases": [], "location_name": "福建", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7cbe6621-e079-5a66-a65e-37d7a3600ce6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

